(function(){
  const frames = [
    'data:image/webp;base64,',
    'data:image/webp;base64,',
    'data:image/webp;base64,',
    'data:image/webp;base64,',
    'data:image/webp;base64,',
    'data:image/webp;base64,',
    'data:image/webp;base64,',
    'data:image/webp;base64,',
    'data:image/webp;base64,',
    'data:image/webp;base64,',
    'data:image/webp;base64,',
    'data:image/webp;base64,',
    'data:image/webp;base64,',
    'data:image/webp;base64,',
    'data:image/webp;base64,',
    'data:image/webp;base64,',
    'data:image/webp;base64,',
    'data:image/webp;base64,',
    'data:image/webp;base64,',
    'data:image/webp;base64,',
    'data:image/webp;base64,',
    'data:image/webp;base64,',
    'data:image/webp;base64,',
    'data:image/webp;base64,',
    'data:image/webp;base64,',
    'data:image/webp;base64,',
    'data:image/webp;base64,',
    'data:image/webp;base64,',
    'data:image/webp;base64,',
    'data:image/webp;base64,',
    'data:image/webp;base64,',
    'data:image/webp;base64,',
    'data:image/webp;base64,',
    'data:image/webp;base64,',
    'data:image/webp;base64,',
    'data:image/webp;base64,',
    'data:image/webp;base64,',
    'data:image/webp;base64,',
    'data:image/webp;base64,',
    'data:image/webp;base64,',
    'data:image/webp;base64,',
    'data:image/webp;base64,',
    'data:image/webp;base64,',
    'data:image/webp;base64,',
    'data:image/webp;base64,',
    'data:image/webp;base64,',
    'data:image/webp;base64,',
    'data:image/webp;base64,',
    'data:image/webp;base64,',
    'data:image/webp;base64,',
    'data:image/webp;base64,',
    'data:image/webp;base64,',
    'data:image/webp;base64,',
    'data:image/webp;base64,',
    'data:image/webp;base64,',
    'data:image/webp;base64,',
    'data:image/webp;base64,',
    'data:image/webp;base64,',
    'data:image/webp;base64,',
    'data:image/webp;base64,',
    'data:image/webp;base64,',
    'data:image/webp;base64,',
    'data:image/webp;base64,',
    'data:image/webp;base64,',
    'data:image/webp;base64,',
    'data:image/webp;base64,',
    'data:image/webp;base64,',
    'data:image/webp;base64,',
    'data:image/webp;base64,',
    'data:image/webp;base64,',
    'data:image/webp;base64,',
    'data:image/webp;base64,',
    'data:image/webp;base64,',
    'data:image/webp;base64,',
    'data:image/webp;base64,',
    'data:image/webp;base64,',
    'data:image/webp;base64,',
    'data:image/webp;base64,',
    'data:image/webp;base64,',
    'data:image/webp;base64,',
    'data:image/webp;base64,'
  ];

  const crane = document.getElementById('craneCompanion');
  const frameEl = document.getElementById('craneFrame');
  const facingEl = document.getElementById('craneFacing');
  const tiltEl = document.getElementById('craneTilt');
  const opening = document.getElementById('lotusOpening');
  if(!crane || !frameEl || !facingEl || !tiltEl) return;

  /* preload all nine frame images */
  frames.forEach(src => { const im=new Image(); im.src=src; });

  const CRANE_W = 176;
  const CRANE_H = 130;

  // 81 帧不是“固定每次都播 81 张”，而是一套高精度 MASTER CYCLE。
  // 每次飞行都会根据距离自动抽样成一个整数帧周期，且每个周期必定：
  // master frame 0 → ... → master frame 80。
  const MASTER_CYCLE_FRAMES = frames.length;   // 81
  const BASE_FRAME_MS = 1000 / 60;             // 目标显示刷新约 60fps
  const REST_FRAME = MASTER_CYCLE_FRAMES - 1; // 到达时停在完整周期的最后一帧

  let x = window.innerWidth * .79;
  let y = window.innerHeight * .24;
  let facing = 1;
  let flightRaf = 0;
  let flightToken = 0;
  let flying = false;
  let downX=0, downY=0, downTime=0;

  function clamp(v,min,max){ return Math.max(min,Math.min(max,v)); }
  function easeInOutCubic(t){
    return t < .5 ? 4*t*t*t : 1-Math.pow(-2*t+2,3)/2;
  }

  function place(nx,ny){
    x=nx; y=ny;
    crane.style.transform=`translate3d(${(x-CRANE_W/2).toFixed(1)}px,${(y-CRANE_H/2).toFixed(1)}px,0)`;
  }

  function setFacing(dir){
    facing=dir < 0 ? -1 : 1;
    facingEl.style.transform=`scaleX(${facing})`;
  }

  function setFrame(index){
    frameEl.src=frames[(index+frames.length)%frames.length];
  }

  function showWhenReady(){
    /* Don't put the crane over the initial lotus opening.
       Once the real workspace appears, the crane becomes a persistent overlay. */
    if(opening && !opening.classList.contains('is-done')){
      setTimeout(showWhenReady,160);
      return;
    }
    place(
      clamp(x,CRANE_W*.52,innerWidth-CRANE_W*.52),
      clamp(y,CRANE_H*.52,innerHeight-CRANE_H*.52)
    );
    setFrame(REST_FRAME);
    setFacing(1);
    crane.classList.add('is-ready');
  }
  setTimeout(showWhenReady,260);

  function spawnWind(wx,wy,angle){
    const w=document.createElement('span');
    w.className='crane-wind';
    w.style.left=(wx-27)+'px';
    w.style.top=wy+'px';
    w.style.transform=`rotate(${angle}deg)`;
    document.body.appendChild(w);
    requestAnimationFrame(()=>w.classList.add('play'));
    setTimeout(()=>w.remove(),700);
  }

  function flyTo(clickX,clickY){
    if(!crane.classList.contains('is-ready')) return;

    const sx=x, sy=y;
    const rawDx=clickX-sx;
    const dir = Math.abs(rawDx) < 3 ? facing : (rawDx >= 0 ? 1 : -1);
    setFacing(dir);

    /* 鹤嘴尽量落在用户真正点击的位置附近；空间轨迹仍然是严格直线。 */
    const beakOffsetX = dir > 0 ? CRANE_W*.36 : -CRANE_W*.36;
    const ex = clamp(clickX - beakOffsetX, CRANE_W*.50, innerWidth-CRANE_W*.50);
    const ey = clamp(clickY - 4, CRANE_H*.50, innerHeight-CRANE_H*.50);

    const dx=ex-sx, dy=ey-sy;
    const dist=Math.hypot(dx,dy);

    /* ================================================================
       整数周期求解器

       1. 先按距离估计“应该完整扇几次翅膀”。
       2. 再按期望飞行速度估算总时长。
       3. 把总显示帧数强制量化成：
            cycleCount × framesPerCycle
          所以任何一次飞行一定是整数个完整周期。
       4. framesPerCycle 会自动变化：
          近距离少取一些 MASTER 帧，远距离多取一些；
          但每个周期一定从 MASTER 第 1 帧完整走到最后一帧。
       ================================================================ */

    // 大约每 300px 一个完整扇翅周期；最少 1 次，最多 6 次。
    const cycleCount = clamp(Math.round(dist / 300), 1, 6);

    // 希望视觉移动速度大致保持在 500~560 px/s。
    const targetDuration = clamp((dist / 525) * 1000, 620, 2600);

    // 在约 60fps 目标下，自动求每个完整周期应该显示多少帧。
    let framesPerCycle = Math.round((targetDuration / BASE_FRAME_MS) / cycleCount);

    // 至少 18 帧/周期保证动作完整；最多使用全部 81 帧。
    framesPerCycle = clamp(framesPerCycle, 18, MASTER_CYCLE_FRAMES);

    const totalDisplayFrames = cycleCount * framesPerCycle;

    // 为了让总时长接近期望值，同时保证帧数仍然是整数周期，
    // 反过来微调每帧实际时长。限制范围避免忽快忽慢。
    const frameMs = clamp(
      targetDuration / Math.max(1,totalDisplayFrames-1),
      12.5,  // 最高约 80fps 时间采样
      28.0   // 最低约 36fps
    );

    const exactDuration = (totalDisplayFrames - 1) * frameMs;

    flightToken++;
    const token=flightToken;
    if(flightRaf) cancelAnimationFrame(flightRaf);

    crane.classList.add('is-flying','has-flown');
    crane.dataset.cycles=String(cycleCount);
    crane.dataset.framesPerCycle=String(framesPerCycle);
    crane.dataset.totalFrames=String(totalDisplayFrames);

    flying=true;
    const start=performance.now();
    let lastDisplayIndex=-1;
    let lastWind=0;

    /* 身体只做很轻的方向倾斜，不改变直线轨迹。 */
    let angle=Math.atan2(dy,Math.max(24,Math.abs(dx)))*180/Math.PI;
    angle=clamp(angle,-7,7);
    tiltEl.style.transform=`rotate(${(dir>0?angle:-angle).toFixed(2)}deg)`;

    function masterIndexFor(displayIndex){
      const inCycle = displayIndex % framesPerCycle;

      // 关键：每一个周期的第 0 帧映射 MASTER 0，
      // 最后一帧精确映射 MASTER 80。
      if(framesPerCycle <= 1) return MASTER_CYCLE_FRAMES - 1;
      const u = inCycle / (framesPerCycle - 1);
      return Math.round(u * (MASTER_CYCLE_FRAMES - 1));
    }

    function tick(now){
      if(token!==flightToken) return;

      const elapsed=now-start;

      // 直接用时间算当前“整数显示帧”，而不是独立循环翅膀。
      let displayIndex=Math.floor(elapsed/frameMs);
      displayIndex=Math.min(totalDisplayFrames-1,displayIndex);

      if(displayIndex!==lastDisplayIndex){
        lastDisplayIndex=displayIndex;

        const masterIndex=masterIndexFor(displayIndex);
        setFrame(masterIndex);

        // 位置进度也绑定同一个整数帧序列。
        // 因此动画最后一帧出现的时刻，就是鹤到达终点的时刻。
        const linearProgress =
          totalDisplayFrames<=1 ? 1 : displayIndex/(totalDisplayFrames-1);

        const t=easeInOutCubic(linearProgress);

        // 空间上仍然严格是 A→B 直线。
        const px=sx + dx*t;
        const py=sy + dy*t;
        place(px,py);

        // 长距离飞行偶尔留下一道非常淡的气流。
        if(dist>300 && now-lastWind>470 && linearProgress>.18 && linearProgress<.82){
          spawnWind(px-dir*60,py+18,dir>0?angle:180-angle);
          lastWind=now;
        }
      }

      if(displayIndex < totalDisplayFrames-1){
        flightRaf=requestAnimationFrame(tick);
      }else{
        /* 完整周期的最后一帧和终点严格同时到达。 */
        flying=false;
        flightRaf=0;
        place(ex,ey);
        tiltEl.style.transform='rotate(0deg)';
        setFrame(MASTER_CYCLE_FRAMES-1);
        crane.classList.remove('is-flying');
      }
    }

    flightRaf=requestAnimationFrame(tick);
  }

  /* True click detection: dragging the workspace does NOT call the crane. */
  document.addEventListener('pointerdown',e=>{
    if(e.pointerType==='touch') return;
    downX=e.clientX; downY=e.clientY; downTime=performance.now();
  },true);

  document.addEventListener('pointerup',e=>{
    if(e.pointerType==='touch' || e.button!==0) return;

    /* Ignore only preview/debug opening controls, not real app navigation. */
    if(e.target.closest('#motionReplay,.lotus-opening')) return;

    const moved=Math.hypot(e.clientX-downX,e.clientY-downY);
    const held=performance.now()-downTime;
    if(moved>11 || held>750) return;

    flyTo(e.clientX,e.clientY);
  },true);

  window.addEventListener('resize',()=>{
    place(
      clamp(x,CRANE_W*.50,innerWidth-CRANE_W*.50),
      clamp(y,CRANE_H*.50,innerHeight-CRANE_H*.50)
    );
  });

  /* Exposed only for preview inspection. */
  window.flyYouHuoCraneTo=flyTo;
})();
